Import ListNotations.
Open Scope bv_scope.
Open Scope Z_scope.
#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_n8 segs m a bs.
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.

Section ANNG.
  Context {HCEIL : HeapCeil}.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (beg len o n lo : Z).
  Hypothesis B8 : beg mod 8 = 0.
  Hypothesis LEN : 0 <= len <= 2^40.
  Hypothesis MO : 0 <= o <= len.
  Hypothesis MN : 0 <= n <= len.
  Hypothesis RNG : app_rng beg (beg + len).
  Hypothesis SH0 : SHAD m beg (cc_gen len o).
  Hypothesis ST0 : stk asegs m lo (bv_unsigned sp).
  Hypothesis CEIL : aceil <= lo.
  Hypothesis LO : lo <= bv_unsigned sp - AINTRIN_STACK.
  Hypothesis MI : mem_inv asegs m.
  Hypothesis AC : ACONST m.
  Hypothesis THR : rw_cells asegs m ACF_CLRTHR_CELL [C8 (Z_to_bv 64 18446744073709551615)].
  Hypothesis DCO : rw_cells asegs m ADCO_CELL [C1 (Z_to_bv 8 1)].
  Hypothesis GVB : rw_cells asegs m AGOT_VERB [C8 (Z_to_bv 64 AVERB_CELL)].
  Hypothesis VB : rw_cells asegs m AVERB_CELL [C4 (Z_to_bv 64 0)].

  Definition agpost : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom asegs)
      /\ munch [(sh beg, sh beg + nsh len); (bv_unsigned sp - AINTRIN_STACK, bv_unsigned sp)]%Z m m'
      /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp)
      /\ SHAD m' beg (cc_gen len n)
      /\ ACONST m'.

  Notation SP2 := (Z_to_bv 64 (bv_unsigned sp + -2128)).
  Notation W := [(sh beg, sh beg + nsh len); (bv_unsigned sp - 4096, bv_unsigned sp)].
  Notation FRAME mm := (rw_cells asegs mm (bv_unsigned sp + -56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).

